const KEY = 'test-key-not-real';

function answerBody(intent: string, confidence: unknown = 0.83, extra: Record<string, unknown> = {}) {
  return {
    model: ROUTE_MODEL,
    answers: {
      intent: {
        type: 'choice',
        choice: intent,
        confidence,
        probabilities: { [intent]: 0.8, research: 0.1, dev_build: 0.05, bogus: 0.9 },
      },
      needs_worktree: { type: 'noul', noul: 0.91 },
      needs_browser: { type: 'noul', noul: 0.05 },
      mutation_risk: { type: 'score', score: 1.2, probabilities: [0.1, 0.6, 0.2, 0.1] },
      needs_operator: { type: 'noul', noul: 0.12 },
      ...extra,
    },
    usage: { input_tokens: 812, output_tokens: 0 },
  };
}

function mockFetch(status: number, body: unknown) {
  return vi.fn(async () => new Response(JSON.stringify(body), { status })) as unknown as typeof fetch;
}

let projectDir: string;
const SESSION = 'route-test-session';

function envFor(mode: string, extra: Record<string, string> = {}): NodeJS.ProcessEnv {
  return { ORK_ROUTE_JEV: mode, ORK_TYPESAFE_API_KEY: KEY, ...extra };
}

