describe('redactor', () => {
  // [name, input, replacement token, the substring that must not survive]
  const cases: Array<[string, string, string, string]> = [
    ['bearer', 'use bearer abcdef123456 here', '[SECRET]', 'abcdef123456'],
    ['token assignment', 'token=abcd1234efgh', '[SECRET]', 'abcd1234efgh'],
    ['jwt', 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIn0.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV', '[SECRET]', 'eyJ'],
    ['ghp', 'ghp_abcdefghijklmnopqrstuvwxyz0123', '[SECRET]', 'ghp_'],
    ['github_pat', 'github_pat_abcdefghijklmnopqrstuvwxyz', '[SECRET]', 'github_pat_'],
    ['sk', 'sk-abcdefghijklmnop', '[SECRET]', 'sk-'],
    ['xox', 'xoxb-1234567890-abc', '[SECRET]', 'xoxb'],
    ['akia', 'AKIAABCDEFGHIJKLMNOP', '[SECRET]', 'AKIA'],
    ['apik', 'apikabcdefghijklmnopqrstuvwxyz', '[SECRET]', 'apik'],
    ['ops', 'ops_abcdefghijklmnopqrstuvwxyz0123', '[SECRET]', 'ops_'],
    ['op ref', 'read op://<vault>/<item>/credential now', '[SECRET]', 'op://'],
    ['hex40', 'commit 0123456789abcdef0123456789abcdef01234567 broke it', '[SECRET]', '0123456789abcdef'],
    ['email', 'mail yonatan.gross+x@example.co.il today', '[EMAIL]', '@'],
    ['phone 05x', 'call 052-123-4567 now', '[PHONE]', '4567'],
    ['phone spaced', 'call 052 123 4567 now', '[PHONE]', '4567'],
    ['phone +972', 'call +972-52-1234567 now', '[PHONE]', '972'],
    ['phone 972 bare', 'call 972521234567 now', '[PHONE]', '972'],
    ['nine digit id', 'id 123456789 please', '[SECRET]', '123456789'],
  ];
  for (const [name, input, token, leak] of cases) {
    it(`redacts ${name}`, () => {
      const out = redactPrompt(input, 1500, null);
      expect(out.text).toContain(token);
      expect(out.count).toBeGreaterThanOrEqual(1);
      expect(out.text).not.toContain(leak);
    });
  }

  it('decodes JSON escapes before matching, so an escaped secret is caught', () => {
    expect(unescapeJson('a\\u003db')).toBe('a=b');
    const out = redactPrompt('token\\u003dabcd1234efgh and x\\u0040y.com', 1500, null);
    expect(out.text).toBe('[SECRET] and [EMAIL]');
    expect(out.count).toBe(2);
  });

  it('keeps a plain prompt intact and counts zero', () => {
    const out = redactPrompt('fix the flaky retry logic in the upload endpoint', 1500, null);
    expect(out.text).toBe('fix the flaky retry logic in the upload endpoint');
    expect(out.count).toBe(0);
  });

  it('truncates to the cap after redaction', () => {
    expect(redactPrompt('x'.repeat(2000), 1500, null).text).toHaveLength(1500);
  });

  it('builds client tokens from directory names: slug, spaced form, long segments', () => {
    const tokens = clientTokensFromNames(['gan-shaked', 'osh_cpa', '_template', '.git', 'demo-site']);
    expect(tokens).toContain('gan-shaked');
    expect(tokens).toContain('gan shaked');
    expect(tokens).toContain('shaked');
    expect(tokens).not.toContain('gan');
    expect(tokens).toContain('osh_cpa');
    expect(tokens).toContain('osh cpa');
    expect(tokens).not.toContain('_template');
    expect(tokens).toContain('demo-site');
    expect(tokens).not.toContain('demo');
    expect(tokens).not.toContain('site');
  });

  it('redacts client slugs, spaced forms and segments, case insensitively', () => {
    const re = buildClientPattern(clientTokensFromNames(['gan-shaked']));
    const out = redactPrompt('prep the call with Gan Shaked and email shaked about gan-shaked', 1500, re);
    expect(out.text).toBe('prep the call with [CLIENT] and email [CLIENT] about [CLIENT]');
    expect(out.count).toBe(3);
  });
});

describe('request and answer', () => {
  it('sends the redacted prompt, a repo basename and the pinned model, and hashes the redacted text', () => {
    const config = resolveRouteConfig({});
    const built = buildRouteRequest('fix it for yonatan@example.com', {
      openingTurn: true,
      repo: 'orchestkit',
      config,
      clientPattern: null,
    });
    expect(built.request.model).toBe('jev-1.13.0');
    expect(built.request.state).toEqual({ prompt: 'fix it for [EMAIL]', opening_turn: true, repo: 'orchestkit' });
    expect(built.request.questions).toBe(ROUTE_QUESTIONS);
    expect(built.redacted).toBe(1);
    expect(built.inputSha256).toBe(sha256('fix it for [EMAIL]'));
    expect(built.inputSha256).not.toBe(sha256('fix it for yonatan@example.com'));
  });

  it('the egress guard refuses a leak on the serialized request, raw or escaped', () => {
    const config = resolveRouteConfig({});
    const clean = buildRouteRequest('fix the retry logic', { openingTurn: false, repo: 'r', config, clientPattern: null });
    expect(egressScan(clean.request, null)).toBeNull();
    const leaked = { ...clean.request, state: { ...clean.request.state, prompt: 'mail a@b.co' } };
    expect(egressScan(leaked, null)).toBe('email');
    const escaped = { ...clean.request, state: { ...clean.request.state, prompt: 'call 052\\u002d123\\u002d4567' } };
    expect(egressScan(escaped, null)).toBe('phone');
    const re = buildClientPattern(clientTokensFromNames(['gan-shaked']));
    const client = { ...clean.request, state: { ...clean.request.state, repo: 'shaked' } };
    expect(egressScan(client, re)).toBe('client');
  });

  it('parses the five answers and drops unknown probability keys', () => {
    const parsed = parseRouteAnswer(answerBody('dev_fix'));
    expect(parsed).not.toBeNull();
    expect(parsed?.intent).toBe('dev_fix');
    expect(parsed?.confidence).toBe(0.83);
    expect(parsed?.probabilities).toEqual({ dev_fix: 0.8, research: 0.1, dev_build: 0.05 });
    expect(parsed?.worktree).toBe(0.91);
    expect(parsed?.browser).toBe(0.05);
    expect(parsed?.mutation).toBe(1.2);
    expect(parsed?.operator).toBe(0.12);
    expect(parsed?.inputTokens).toBe(812);
  });

  it('rejects a choice outside the closed set and a bodiless response', () => {
    expect(parseRouteAnswer(answerBody('bogus'))).toBeNull();
    expect(parseRouteAnswer({})).toBeNull();
    expect(parseRouteAnswer(null)).toBeNull();
  });
});

describe('routeJudgment (async, shadow)', () => {
  it('records and returns table in shadow mode, no prompt text on disk, file mode 0600', async () => {
    const fetchImpl = mockFetch(200, answerBody('dev_fix'));
    const verdict = await routeJudgment({
      prompt: 'fix the flaky retry for yonatan@example.com',
      sessionId: SESSION,
      projectDir,
      env: envFor('shadow'),
      clientNames: [],
      fetchImpl,
    });
    expect(verdict.decided_by).toBe('table');
    expect(verdict.intent).toBe('dev_fix');
    expect(verdict.conf).toBe(0.83);
    expect(verdict.redacted).toBe(1);
    expect(verdict.target).toEqual({ kind: 'skill', name: 'fix-issue' });
    expect(verdict.top3[0]).toEqual(['dev_fix', 0.8]);
    const file = join(routeSessionDir(SESSION, projectDir, {}), FILE_ROUTE_RECORDS);
    const raw = readFileSync(file, 'utf8');
    expect(raw).not.toContain('flaky');
    expect(raw).not.toContain('example.com');
    expect(statSync(file).mode & 0o777).toBe(0o600);
    const rec = JSON.parse(raw.trim());
    expect(rec.input_sha256).toBe(sha256('fix the flaky retry for [EMAIL]'));
    expect(rec.decided_by).toBe('table');
    expect(rec.flag).toBe('shadow');
    expect(rec.input_tokens).toBe(812);
    // the request carried the redacted text and the bearer header
    const call = (fetchImpl as unknown as ReturnType<typeof vi.fn>).mock.calls[0] as [string, RequestInit];
    expect(call[0]).toBe('https://api.typesafe.ai/v1/systemone');
    expect((call[1].headers as Record<string, string>).Authorization).toBe(`Bearer ${KEY}`);
    expect(String(call[1].body)).toContain('[EMAIL]');
    expect(String(call[1].body)).not.toContain('example.com');
  });

  it('is off with the flag unset and calls nothing', async () => {
    const fetchImpl = mockFetch(200, answerBody('dev_fix'));
    const verdict = await routeJudgment({ prompt: 'fix it now please', sessionId: SESSION, projectDir, env: {}, fetchImpl });
    expect(verdict.decided_by).toBe('off');
    expect(fetchImpl).not.toHaveBeenCalled();
  });

  it('falls back to the table with no key', async () => {
    const fetchImpl = mockFetch(200, answerBody('dev_fix'));
    const verdict = await routeJudgment({
      prompt: 'fix it now please',
      sessionId: SESSION,
      projectDir,
      env: { ORK_ROUTE_JEV: 'steer' },
      fetchImpl,
    });
    expect(verdict.decided_by).toBe('table');
    expect(verdict.error).toBe('no key');
    expect(fetchImpl).not.toHaveBeenCalled();
  });

  it('refuses the call when a leak survives redaction (egress, fail closed)', async () => {
    // A two-segment token starting with eyJ is not a full JWT, so the redactor
    // leaves it, but the guard's looser JWT prefix shape refuses it.
    const fetchImpl = mockFetch(200, answerBody('dev_fix'));
    const verdict = await routeJudgment({
      prompt: 'fix eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9. now',
      sessionId: SESSION,
      projectDir,
      env: envFor('steer'),
      clientNames: [],
      fetchImpl,
    });
    expect(verdict.decided_by).toBe('egress');
    expect(verdict.error).toBe('egress secret');
    expect(fetchImpl).not.toHaveBeenCalled();
    const raw = readFileSync(join(routeSessionDir(SESSION, projectDir, {}), FILE_ROUTE_RECORDS), 'utf8');
    expect(JSON.parse(raw.trim()).decided_by).toBe('egress');
    expect(raw).not.toContain('eyJ');
  });

  it('a dead lane (fetch throws) is table with an error name, never a throw', async () => {
    const fetchImpl = vi.fn(async () => {
      throw new TypeError('fetch failed');
    }) as unknown as typeof fetch;
    const verdict = await routeJudgment({ prompt: 'fix it now please', sessionId: SESSION, projectDir, env: envFor('steer'), fetchImpl });
    expect(verdict.decided_by).toBe('table');
    expect(verdict.error).toBe('TypeError');
    expect(verdict.intent).toBeNull();
  });

  it('a timeout is table with error timeout', async () => {
    const fetchImpl = vi.fn(
      (_url: string, init: RequestInit) =>
        new Promise<Response>((_resolve, reject) => {
          init.signal?.addEventListener('abort', () => reject(new DOMException('aborted', 'AbortError')));
        }),
    ) as unknown as typeof fetch;
    const verdict = await routeJudgment({
      prompt: 'fix it now please',
      sessionId: SESSION,
      projectDir,
      env: envFor('steer', { ORK_ROUTE_JEV_TIMEOUT_MS: '20' }),
      fetchImpl,
    });
    expect(verdict.decided_by).toBe('table');
    expect(verdict.error).toBe('timeout');
  });

  it('a malformed body is table', async () => {
    const fetchImpl = mockFetch(200, { answers: { intent: { choice: 'nope' } } });
    const verdict = await routeJudgment({ prompt: 'fix it now please', sessionId: SESSION, projectDir, env: envFor('steer'), fetchImpl });
    expect(verdict.decided_by).toBe('table');
    expect(verdict.error).toBe('malformed answer');
  });

  it('steer above the floor decides by jev; below the floor by the table', async () => {
    const above = await routeJudgment({
      prompt: 'fix it now please',
      sessionId: SESSION,
      projectDir,
      env: envFor('steer'),
      fetchImpl: mockFetch(200, answerBody('dev_build', 0.71)),
    });
    expect(above.decided_by).toBe('jev');
    expect(above.target).toEqual({ kind: 'skill', name: 'implement' });
    const below = await routeJudgment({
      prompt: 'fix it now please',
      sessionId: SESSION,
      projectDir,
      env: envFor('steer'),
      fetchImpl: mockFetch(200, answerBody('dev_build', 0.31)),
    });
    expect(below.decided_by).toBe('table');
    expect(below.intent).toBe('dev_build');
    const raised = await routeJudgment({
      prompt: 'fix it now please',
      sessionId: SESSION,
      projectDir,
      env: envFor('steer', { ORK_ROUTE_JEV_FLOOR: '0.9' }),
      fetchImpl: mockFetch(200, answerBody('dev_build', 0.71)),
    });
    expect(raised.decided_by).toBe('table');
    expect(raised.floor).toBe(0.9);
  });
});

describe('balance guard', () => {
  it('counts input tokens per UTC day and stops calling once the budget is spent', async () => {
    const dataDir = routeDataDir(projectDir, {});
    const env = envFor('shadow', { ORK_ROUTE_JEV_DAILY_TOKENS: '1000' });
    const first = mockFetch(200, answerBody('dev_fix'));
    await routeJudgment({ prompt: 'fix it now please', sessionId: SESSION, projectDir, env, fetchImpl: first });
    expect(JSON.parse(readFileSync(join(dataDir, FILE_ROUTE_BUDGET), 'utf8')).tokens).toBe(812);
    const second = mockFetch(200, answerBody('dev_fix'));
    await routeJudgment({ prompt: 'fix it now please', sessionId: SESSION, projectDir, env, fetchImpl: second });
    expect(JSON.parse(readFileSync(join(dataDir, FILE_ROUTE_BUDGET), 'utf8')).tokens).toBe(1624);
    const third = mockFetch(200, answerBody('dev_fix'));
    const verdict = await routeJudgment({ prompt: 'fix it now please', sessionId: SESSION, projectDir, env, fetchImpl: third });
    expect(verdict.decided_by).toBe('budget');
    expect(verdict.error).toBe('daily tokens');
    expect(third).not.toHaveBeenCalled();
  });

  it('a stale budget day resets the count', () => {
    const dataDir = routeDataDir(projectDir, {});
    mkdirSync(dataDir, { recursive: true });
    writeFileSync(join(dataDir, FILE_ROUTE_BUDGET), JSON.stringify({ day: '2020-01-01', tokens: 999999999 }));
    const verdictPromise = routeJudgment({
      prompt: 'fix it now please',
      sessionId: SESSION,
      projectDir,
      env: envFor('shadow'),
      fetchImpl: mockFetch(200, answerBody('dev_fix')),
    });
    return verdictPromise.then((v) => expect(v.decided_by).toBe('table'));
  });

  it('a 402 trips the seam for 24 hours with one warning; a 429 does the same', async () => {
    const dataDir = routeDataDir(projectDir, {});
    const log = vi.fn();
    const tripped = await routeJudgment({
      prompt: 'fix it now please',
      sessionId: SESSION,
      projectDir,
      env: envFor('steer'),
      fetchImpl: mockFetch(402, { error: 'payment required' }),
      log,
    });
    expect(tripped.decided_by).toBe('table');
    expect(tripped.error).toBe('http 402');
    expect(log).toHaveBeenCalledWith(expect.stringContaining('http 402'), 'warn');
    const marker = JSON.parse(readFileSync(join(dataDir, FILE_ROUTE_TRIPPED), 'utf8'));
    expect(marker.status).toBe(402);
    const next = mockFetch(200, answerBody('dev_fix'));
    const after = await routeJudgment({ prompt: 'fix it now please', sessionId: SESSION, projectDir, env: envFor('steer'), fetchImpl: next });
    expect(after.decided_by).toBe('budget');
    expect(after.error).toBe('tripped');
    expect(next).not.toHaveBeenCalled();
    // 25 hours later the trip has expired
    const later = await routeJudgment({
      prompt: 'fix it now please',
      sessionId: SESSION,
      projectDir,
      env: envFor('steer'),
      fetchImpl: mockFetch(429, {}),
      now: () => Date.now() + 25 * 3_600_000,
    });
    expect(later.error).toBe('http 429');
  });
});

describe('synchronous child transport (steer)', () => {
  it('parses a spawn reply into the same result shape as fetch', () => {
    const config = resolveRouteConfig({ ORK_ROUTE_JEV: 'steer' });
    const request = buildRouteRequest('fix it', { openingTurn: false, repo: 'r', config, clientPattern: null }).request;
    const spawnImpl = vi.fn((_cmd: string, args: string[], opts: { input: string; env: NodeJS.ProcessEnv }) => {
      expect(args[0]).toBe('-e');
      expect(args[1]).toBe(ROUTE_CHILD_SCRIPT);
      expect(args.join(' ')).not.toContain(KEY);
      expect(opts.env.ORK_TYPESAFE_API_KEY).toBe(KEY);
      expect(JSON.parse(opts.input).state.prompt).toBe('fix it');
      return { status: 0, stdout: JSON.stringify({ status: 200, text: JSON.stringify(answerBody('dev_fix')), latencyMs: 5 }) };
    });
    const ok = postRouteRequestSync(request, KEY, config, spawnImpl);
    expect(ok.ok).toBe(true);
    if (ok.ok) expect(parseRouteAnswer(ok.body)?.intent).toBe('dev_fix');

    const bad = postRouteRequestSync(request, KEY, config, () => ({
      status: 0,
      stdout: JSON.stringify({ status: 402, text: '{}', latencyMs: 5 }),
    }));
    expect(bad).toMatchObject({ ok: false, error: 'http 402', status: 402 });

    const timeout = postRouteRequestSync(request, KEY, config, () => ({
      status: 0,
      stdout: JSON.stringify({ error: 'timeout', latencyMs: 3000 }),
    }));
    expect(timeout).toMatchObject({ ok: false, error: 'timeout' });

    const crashed = postRouteRequestSync(request, KEY, config, () => ({ status: 1, stdout: '' }));
    expect(crashed).toMatchObject({ ok: false, error: 'child failed' });
  });

  it('routeJudgmentSync steers through the injected spawn', () => {
    const verdict = routeJudgmentSync({
      prompt: 'fix it now please',
      sessionId: SESSION,
      projectDir,
      env: envFor('steer'),
      spawnImpl: () => ({
        status: 0,
        stdout: JSON.stringify({ status: 200, text: JSON.stringify(answerBody('dev_review', 0.9)), latencyMs: 7 }),
      }),
    });
    expect(verdict.decided_by).toBe('jev');
    expect(verdict.target).toEqual({ kind: 'skill', name: 'review-pr' });
  });

  it('the child script posts stdin with the bearer header and returns one JSON line', async () => {
    let seenAuth = '';
    let seenBody = '';
    const server: Server = createServer((req, res) => {
      seenAuth = String(req.headers.authorization);
      let data = '';
      req.on('data', (d) => {
        data += d;
      });
      req.on('end', () => {
        seenBody = data;
        res.writeHead(200, { 'content-type': 'application/json' });
        res.end(JSON.stringify(answerBody('dev_fix')));
      });
    });
    await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
    const address = server.address();
    const port = typeof address === 'object' && address ? address.port : 0;
    try {
      const stdout = await new Promise<string>((resolve, reject) => {
        const child = spawn(process.execPath, ['-e', ROUTE_CHILD_SCRIPT], {
          env: {
            PATH: process.env.PATH || '',
            ORK_TYPESAFE_API_KEY: KEY,
            ORK_ROUTE_JEV_ENDPOINT: `http://127.0.0.1:${port}/v1/systemone`,
            ORK_ROUTE_JEV_TIMEOUT_MS: '3000',
          },
        });
        let out = '';
        child.stdout.on('data', (d) => {
          out += d;
        });
        child.on('error', reject);
        child.on('close', () => resolve(out));
        child.stdin.end(JSON.stringify({ state: { prompt: 'fix it' } }));
      });
      const reply = JSON.parse(stdout);
      expect(reply.status).toBe(200);
      expect(JSON.parse(reply.text).answers.intent.choice).toBe('dev_fix');
      expect(seenAuth).toBe(`Bearer ${KEY}`);
      expect(JSON.parse(seenBody).state.prompt).toBe('fix it');
    } finally {
      await new Promise<void>((resolve) => server.close(() => resolve()));
    }
  }, 15_000);
});

